import React, { createContext, useContext, useState, useCallback } from 'react';

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  customerPhone: string;
  address: string;
  coordinates: { lat: number; lng: number };
  assignedEmployeeId: string;
  status: string;
  priority: string;
  orderTime: string;
  estimatedDeliveryTime: string;
  actualDeliveryTime: string | null;
  delayStatus: string;
  delayReason: string | null;
  weatherImpact: boolean;
  trafficImpact: boolean;
  items: Array<{ name: string; weight?: string; dimensions?: string; quantity?: number }>;
  value: number;
  paymentMethod: string;
  pickupAddress: string;
  customerAbsence: boolean;
  absenceHistory: Array<{
    date: string;
    reason: string;
    notified: boolean;
  }>;
  routeOptimization: {
    mainRoute: {
      distance: number;
      duration: number;
      geometry?: string;
      waypoints?: Array<{ lat: number; lng: number }>;
    };
    optimizedRoute: {
      distance: number;
      duration: number;
      geometry?: string;
      waypoints?: Array<{ lat: number; lng: number }>;
    };
    isOptimized: boolean;
  };
  trafficZones: Array<{
    lat: number;
    lng: number;
    severity: 'low' | 'medium' | 'high';
  }>;
  currentLocation?: string;
  lastUpdate?: string;
  trackingNumber?: string;
}

export interface Employee {
  id: string;
  name: string;
  email: string;
  phone: string;
  password?: string;
  status: string;
  currentLocation: { lat: number; lng: number };
  vehicleType: string;
  maxOrders: number;
  currentOrders: number;
  onBreak: boolean;
  skills: string[];
  rating: number;
  orders?: Order[];
  notifications: Notification[];
}

export interface Notification {
  id: string;
  orderId: string;
  message: string;
  timestamp: Date;
  type: 'info' | 'warning' | 'success';
}

interface SharedDataContextType {
  orders: Order[];
  employees: Employee[];
  notifications: Notification[];
  updateOrder: (orderId: string, updates: Partial<Order>) => void;
  updateEmployee: (employeeId: string, updates: Partial<Employee>) => void;
  addNotification: (notification: Notification) => void;
  getOrderById: (orderId: string) => Order | undefined;
  getEmployeeById: (employeeId: string) => Employee | undefined;
  getOrdersByEmployeeId: (employeeId: string) => Order[];
  notifyCustomer: (orderId: string, message: string) => void;
}

const initialOrders: Order[] = [
  {
    id: 'ORD003',
    customerId: 'CUST003',
    customerName: 'Riddhi Bose',
    customerPhone: '+919205413301',
    address: 'ABES Engineering College, NH-24 Highway, Ghaziabad, Uttar Pradesh 201009',
    coordinates: { lat: 28.6789, lng: 77.4567 },
    assignedEmployeeId: 'EMP004',
    status: 'in_transit',
    priority: 'express',
    orderTime: new Date('2026-04-26T14:00:00').toISOString(),
    estimatedDeliveryTime: new Date('2026-04-26T16:30:00').toISOString(),
    actualDeliveryTime: null,
    delayStatus: 'delayed',
    delayReason: 'Heavy traffic congestion on NH-24 near Ghaziabad',
    weatherImpact: false,
    trafficImpact: true,
    items: [{ name: 'Priority Documents', weight: '0.5kg', dimensions: '25x20x5cm', quantity: 1 }],
    value: 2500,
    paymentMethod: 'cod',
    pickupAddress: 'Gaur City Mall, Greater Noida, Uttar Pradesh 201308',
    customerAbsence: true,
    absenceHistory: [
      { date: '2026-04-25', reason: 'Customer not available at delivery address', notified: false },
      { date: '2026-04-24', reason: 'Customer requested delayed delivery', notified: true }
    ],
    routeOptimization: {
      mainRoute: {
        distance: 18.5,
        duration: 65,
        geometry: 'main_route_polyline_3',
        waypoints: [
          { lat: 28.6082, lng: 77.3689 },
          { lat: 28.6789, lng: 77.4567 }
        ]
      },
      optimizedRoute: {
        distance: 22.1,
        duration: 78,
        geometry: 'optimized_route_polyline_3',
        waypoints: [
          { lat: 28.6082, lng: 77.3689 },
          { lat: 28.6350, lng: 77.4200 },
          { lat: 28.6789, lng: 77.4567 }
        ]
      },
      isOptimized: false
    },
    trafficZones: [
      { lat: 28.6350, lng: 77.4200, severity: 'high' },
      { lat: 28.6500, lng: 77.4350, severity: 'medium' },
      { lat: 28.6600, lng: 77.4450, severity: 'high' }
    ],
    currentLocation: 'En route via NH-24, Ghaziabad',
    lastUpdate: '2026-04-26 14:30 PM',
    trackingNumber: 'TRK-RIDHI003'
  },
  {
    id: 'ORD001',
    customerId: 'CUST001',
    customerName: 'Anjali Verma',
    customerPhone: '+91-9876543201',
    address: 'Sector 62, Noida, Uttar Pradesh 201309',
    coordinates: { lat: 28.5846, lng: 77.3695 },
    assignedEmployeeId: 'EMP001',
    status: 'in_transit',
    priority: 'standard',
    orderTime: new Date('2026-04-26T09:00:00').toISOString(),
    estimatedDeliveryTime: new Date('2026-04-26T14:00:00').toISOString(),
    actualDeliveryTime: null,
    delayStatus: 'none',
    delayReason: null,
    weatherImpact: false,
    trafficImpact: true,
    items: [{ name: 'Electronics Package', weight: '2kg', dimensions: '30x20x10cm' }],
    value: 15000,
    paymentMethod: 'cod',
    pickupAddress: 'Warehouse A, Delhi',
    customerAbsence: false,
    absenceHistory: [],
    routeOptimization: {
      mainRoute: {
        distance: 15.2,
        duration: 35,
        geometry: 'main_route_polyline',
        waypoints: [
          { lat: 28.6692, lng: 77.4538 },
          { lat: 28.5846, lng: 77.3695 }
        ]
      },
      optimizedRoute: {
        distance: 14.8,
        duration: 32,
        geometry: 'optimized_route_polyline',
        waypoints: [
          { lat: 28.6692, lng: 77.4538 },
          { lat: 28.6200, lng: 77.3800 },
          { lat: 28.5846, lng: 77.3695 }
        ]
      },
      isOptimized: false
    },
    trafficZones: [
      { lat: 28.6300, lng: 77.4000, severity: 'high' },
      { lat: 28.6000, lng: 77.3800, severity: 'medium' }
    ]
  }
];

const initialEmployees: Employee[] = [
  {
    id: 'EMP001',
    name: 'Rajesh Kumar',
    email: 'rajesh.k@smartlogistics.com',
    phone: '+91-9876543210',
    password: 'password123',
    status: 'active',
    currentLocation: { lat: 28.6692, lng: 77.4538 },
    vehicleType: 'motorcycle',
    maxOrders: 8,
    currentOrders: 3,
    onBreak: false,
    skills: ['express', 'standard'],
    rating: 4.8,
    notifications: []
  },
  {
    id: 'EMP004',
    name: 'Pakhi Dubey',
    email: 'pakhi.d@smartlogistics.com',
    phone: '+917380729261',
    password: 'Pakhi@2024#Demo',
    status: 'active',
    currentLocation: { lat: 28.6082, lng: 77.3689 },
    vehicleType: 'motorcycle',
    maxOrders: 10,
    currentOrders: 3,
    onBreak: false,
    skills: ['express', 'standard', 'bulk'],
    rating: 4.9,
    notifications: []
  }
];

const SharedDataContext = createContext<SharedDataContextType | undefined>(undefined);

export const SharedDataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [orders, setOrders] = useState<Order[]>(initialOrders);
  const [employees, setEmployees] = useState<Employee[]>(initialEmployees);
  const [notifications, setNotifications] = useState<Notification[]>([]);

  const updateOrder = useCallback((orderId: string, updates: Partial<Order>) => {
    setOrders(prev => prev.map(order => 
      order.id === orderId ? { ...order, ...updates, lastUpdate: new Date().toLocaleString() } : order
    ));
  }, []);

  const updateEmployee = useCallback((employeeId: string, updates: Partial<Employee>) => {
    setEmployees(prev => prev.map(emp => 
      emp.id === employeeId ? { ...emp, ...updates } : emp
    ));
  }, []);

  const addNotification = useCallback((notification: Notification) => {
    setNotifications(prev => [notification, ...prev].slice(0, 50));
  }, []);

  const getOrderById = useCallback((orderId: string) => {
    return orders.find(o => o.id === orderId);
  }, [orders]);

  const getEmployeeById = useCallback((employeeId: string) => {
    return employees.find(e => e.id === employeeId);
  }, [employees]);

  const getOrdersByEmployeeId = useCallback((employeeId: string) => {
    return orders.filter(o => o.assignedEmployeeId === employeeId);
  }, [orders]);

  const notifyCustomer = useCallback((orderId: string, message: string) => {
    const order = orders.find(o => o.id === orderId);
    if (order) {
      addNotification({
        id: `notify_${Date.now()}`,
        orderId,
        message: `Customer ${order.customerName} notified: ${message}`,
        timestamp: new Date(),
        type: 'success'
      });

      updateOrder(orderId, {
        customerAbsence: false,
        absenceHistory: [
          ...order.absenceHistory,
          { date: new Date().toISOString(), reason: `Notified: ${message}`, notified: true }
        ]
      });
    }
  }, [orders, addNotification, updateOrder]);

  return (
    <SharedDataContext.Provider value={{
      orders,
      employees,
      notifications,
      updateOrder,
      updateEmployee,
      addNotification,
      getOrderById,
      getEmployeeById,
      getOrdersByEmployeeId,
      notifyCustomer
    }}>
      {children}
    </SharedDataContext.Provider>
  );
};

export const useSharedData = () => {
  const context = useContext(SharedDataContext);
  if (context === undefined) {
    throw new Error('useSharedData must be used within a SharedDataProvider');
  }
  return context;
};
